+constexpr size_t INPUT_G_IDX = 3;
+constexpr size_t INPUT_A_LOG_IDX = 5;
+constexpr size_t INPUT_DT_BIAS_IDX = 6;
+constexpr size_t INPUT_INITIAL_STATE_IDX = 7;
