+            static_cast<uint32_t>(KDA_FWD_H_DIM * sizeof(T)),
+            0,
+            static_cast<uint32_t>((heads_ * KDA_FWD_H_DIM - KDA_FWD_H_DIM) * sizeof(T)),
+            0};
+        DataCopyPad(attnOut_[OutputOffset(b, hv, tokenStart)], src, params);
+    }
