+    AscendC::MicroAPI::RegTensor<float> &zeroReg,
+    AscendC::MicroAPI::RegTensor<float> &oneReg,
+    __ubuf__ InputT *src,
+    AscendC::MicroAPI::MaskReg &inputMask)
