+    __aicore__ inline uint64_t QOffset(uint64_t b, uint64_t h, uint64_t t, uint64_t d) const
+    {
+        if (inputSequenceMajor_) {
+            return ((b * T_ + t) * H_ + h) * K_ + d;
+        }
+        return ((b * H_ + h) * T_ + t) * K_ + d;
+    }
