+    __aicore__ inline uint64_t SolveScratchOffset(uint64_t b, uint64_t hv, uint64_t chunkIdx,
+                                                  uint64_t slot) const
+    {
+        (void)b;
+        (void)hv;
+        (void)chunkIdx;
+        uint64_t matrixElements = BT_ * BT_;
