+    __aicore__ inline void ProcessChunkPostAicTyped(uint64_t b, uint64_t hv, uint64_t chunkIdx, uint64_t start,
+                                                    uint64_t end)
+    {
+        uint64_t curT = end - start;
+        if (curT == 0 || !UsePostWuCube(curT)) {
+            return;
+        }
+        ComputePostWuCube(b, hv, chunkIdx, start, curT);
