+            return GateStageElems() * (3 * sizeof(T) + sizeof(GK_T)) +
+                   GatePipelineRows() * sizeof(BETA_T);
+        }
+#endif
+        return GateStageElems() * (2 * sizeof(T) + sizeof(GK_T));
+    }
