+    __aicore__ inline void ComputeRawAqkAkkCube(uint64_t b, uint64_t hv, uint64_t chunkIdx,
+                                                uint64_t start, uint64_t curT)
+    {
+        ComputeRawAqkAkkCubeBlock(b, hv, chunkIdx, start, curT, 0, curT);
+    }
