+                l1BaseOffset + static_cast<uint32_t>(lane) * l1LaneBytes);
+            LocalTensor<ElementB> l1B = resource.l1Buf.template GetBufferByByte<ElementB>(
+                l1BaseOffset + static_cast<uint32_t>(lane) * l1LaneBytes + l1ABytes);
