+    __aicore__ inline void CopyLocalFloat(LocalTensor<float> dst, LocalTensor<float> src, uint64_t count)
+    {
+        if (count == 0) {
+            return;
+        }
+        Adds(dst, src, 0.0f, static_cast<uint32_t>(count));
+        PipeBarrier<PIPE_V>();
+    }
