+    __aicore__ inline void BuildPrefixMask(LocalTensor<float> dst, uint64_t prefix, uint64_t count)
+    {
+        if (prefix > count) {
+            prefix = count;
+        }
+        Duplicate(dst, 0.0f, static_cast<uint32_t>(count));
+        if (prefix > 0) {
+            Duplicate(dst, 1.0f, static_cast<uint32_t>(prefix));
+        }
+        PipeBarrier<PIPE_V>();
+    }
