+    __aicore__ inline uint64_t BuildCausalMask(uint64_t threshold, uint64_t colBegin) const
+    {
+        if (threshold <= colBegin) {
+            return ~0ULL;
+        }
+        if (threshold >= colBegin + KDA_SOLVE_BT) {
+            return 0ULL;
+        }
+        return ~0ULL << (threshold - colBegin);
+    }
