+        }
+        SetFlag<HardEvent::MTE3_MTE2>(mte3ToMte2Events_[0]);
+        WaitFlag<HardEvent::MTE3_MTE2>(mte3ToMte2Events_[0]);
+        SetFlag<HardEvent::MTE3_V>(mte3ToVEvent_);
+        WaitFlag<HardEvent::MTE3_V>(mte3ToVEvent_);
+    }
