+            }
+        }
+    }
+
+    __aicore__ inline void ProcessPreAic()
+    {
+        if constexpr (IsSameType<T, float>::value) {
+            return;
+        }
+#if defined(__CCE_AICORE__) && __CCE_AICORE__ == 310
+        if constexpr (SAFE_GATE) {
