+                if constexpr (SAFE_GATE) {
+                    activeSolveSlot_ = localTaskIdx % KDA_SOLVE_PIPELINE_DEPTH;
+                }
+                (void)seq;
+                (void)h;
+                ProcessChunkPreAic(b, hv, chunkIdx, start, end);
+            }
+        }
+    }
