+template <typename TilingData>
+__aicore__ inline GateRuntimeTiling MakeGateTiling(const TilingData &tiling)
+{
+    return {
+        tiling.batch,
+        tiling.seqlen,
+        tiling.vHeadNum,
+        tiling.kHeadDim,
+        tiling.inputRank,
+        tiling.chunkSize,
+        tiling.seqNum,
+        tiling.isVarLen ? 1 : 0,
+        tiling.hasALog ? 1 : 0,
+        tiling.hasDtBias ? 1 : 0,
+        tiling.gateDataType,
+        tiling.useGateInKernel ? 1 : 0,
+        tiling.safeGate ? 1 : 0,
+        tiling.inputSequenceMajor ? 1 : 0,
+        tiling.lowerBound,
+        tiling.gateUsedCoreNum,
+    };
+}
