+        (void)hv;
+        (void)chunkIdx;
+        constexpr uint64_t solvePipelineDepth = SAFE_GATE ? KDA_SOLVE_PIPELINE_DEPTH : 1;
+        uint64_t matrixElements = BT_ * BT_;
+        return ((solveCoreIdx_ * solvePipelineDepth + activeSolveSlot_) * KDA_SOLVE_SCRATCH_SLOTS + slot) *
+               matrixElements;
