+std::string GetShapeStr(const gert::Shape &aShape)
+{
+    std::string shapeStr = "[";
+    for (size_t i = 0; i < aShape.GetDimNum(); ++i) {
+        shapeStr += std::to_string(aShape.GetDim(i)) + (i + 1 < aShape.GetDimNum() ? ", " : "");
+    }
+    return shapeStr + "]";
+}
