+// INPUT
+constexpr uint32_t WEIGHT_DQ_INDEX = 1;
+constexpr uint32_t WEIGHT_UQ_QR_INDEX = 2;
+constexpr uint32_t WEIGHT_DKV_KR_INDEX = 4;
+constexpr uint32_t QUANT_SCALE_CKV_INDEX = 16;
