+constexpr uint32_t DEQUANT_SCALE_Q_NOPE_INDEX = 4;
+constexpr uint32_t QUERY_NORM_INDEX = 5;
+constexpr uint32_t DEQUANT_SCALE_Q_NORM_INDEX = 6;
+// ATTRIBUTE
+constexpr uint32_t ATTR_QUERY_NORM_FLAG_INDEX = 3;
