+    int64_t vUpdateWorkspaceOffset;
+    int64_t kDecayWorkspaceOffset;
+    int64_t hWorkspaceOffset;
+    int64_t numSeqWorkspaceOffset;
+    int64_t numChunksWorkspaceOffset;
